-- NOTIFICATION-REVIEW-2026-11-25: 27 events that were in-app only are also sent by e-mail, with e-mail wording written for them. System Configuration Changed stays in-app
-- only (it is raised very often); it has e-mail wording that an administrator can turn on.
-- A policy an administrator already saved (updated_by set) is not touched. The e-mail wording that the first backfill seeded from the in-app text is removed so that the start-up
-- seeds the written wording; wording an administrator edited (another change summary) is never removed.
delete from notification_template_versions t using notification_policies p
 where t.policy_id = p.id and t.channel = 'EMAIL' and t.change_summary like 'Seeded default e-mail content (the event is sent in-app by default)%'
   and p.event_code in ('access_review.campaign_completed', 'audit.review_campaign_changed', 'audit_trail.export_completed', 'backup.inspection_decided', 'backup.rehearsal_requested', 'backup.store_scrub_started', 'controlled_copy.recall_evidence_uploaded', 'controlled_copy.request_decided', 'document.editing_lock_changed', 'document.legacy_import_finished', 'document.number_changed', 'knowledge.sharing_changed', 'report.template_decided', 'report.type_or_property_changed', 'security.access_profile_changed_audit', 'security.object_access_rule_changed', 'security.permission_set_changed', 'system.configuration_changed', 'system.retention_blocked_deletion', 'uncontrolled_copy.request_decided', 'controlled_copy.destroyed', 'controlled_copy.distributed', 'document.published', 'document.review_completed', 'knowledge.document_published', 'system.maintenance_scheduled', 'training.content_rejected', 'training.session_changed');

update notification_policies set enabled_channels = 'IN_APP,EMAIL', updated_at = now()
 where updated_by is null and enabled_channels = 'IN_APP'
   and event_code in ('access_review.campaign_completed', 'audit.review_campaign_changed', 'audit_trail.export_completed', 'backup.inspection_decided', 'backup.rehearsal_requested', 'backup.store_scrub_started', 'controlled_copy.recall_evidence_uploaded', 'controlled_copy.request_decided', 'document.editing_lock_changed', 'document.legacy_import_finished', 'document.number_changed', 'knowledge.sharing_changed', 'report.template_decided', 'report.type_or_property_changed', 'security.access_profile_changed_audit', 'security.object_access_rule_changed', 'security.permission_set_changed', 'system.retention_blocked_deletion', 'uncontrolled_copy.request_decided', 'controlled_copy.destroyed', 'controlled_copy.distributed', 'document.published', 'document.review_completed', 'knowledge.document_published', 'system.maintenance_scheduled', 'training.content_rejected', 'training.session_changed');
